#include <type_traits>

template<int Metres, int Seconds>
struct Quantity {
    double value{};
};

template<int M1, int S1, int M2, int S2>
constexpr Quantity<M1 + M2, S1 + S2> operator*(Quantity<M1, S1> left,
                                               Quantity<M2, S2> right) {
    return {left.value * right.value};
}

template<int M1, int S1, int M2, int S2>
constexpr Quantity<M1 - M2, S1 - S2> operator/(Quantity<M1, S1> left,
                                               Quantity<M2, S2> right) {
    return {left.value / right.value};
}

// One M and one S for both operands: adding metres to seconds is not a
// rejected call, it is a deduction failure - there is no candidate at all.
template<int M, int S>
constexpr Quantity<M, S> operator+(Quantity<M, S> left, Quantity<M, S> right) {
    return {left.value + right.value};
}

using Metres = Quantity<1, 0>;
using Seconds = Quantity<0, 1>;
using MetresPerSecond = Quantity<1, -1>;

static_assert(std::is_same_v<decltype(Metres{10.0} / Seconds{2.0}),
                             MetresPerSecond>);
static_assert((Metres{10.0} / Seconds{2.0}).value == 5.0);
static_assert(std::is_same_v<decltype(MetresPerSecond{5.0} * Seconds{2.0}),
                             Metres>);
static_assert(!std::is_same_v<Metres, Seconds>);
static_assert(std::is_same_v<decltype(Metres{1.0} + Metres{2.0}), Metres>);

