struct Sample {
    double value;
};

// A template-template parameter earns its keep only because the sink forms
// Buffer<Sample> itself. If the caller already had a container object, a
// constrained "class Container" parameter would be simpler and would not
// constrain the argument's parameter shape at all.
template<template<class...> class Buffer>
class MetricSink {
public:
    void record(Sample sample) { samples_.push_back(sample); }
    std::size_t count() const { return samples_.size(); }

private:
    Buffer<Sample> samples_;
};

// std::array is template<class, std::size_t>: its second parameter is a value,
// so it does not match template<class...> class no matter how many defaults
// it has. A fixed-shape family needs a parameter declared in that shape.
template<template<class, std::size_t> class Buffer, std::size_t Capacity>
class BoundedMetricSink {
public:
    void record(Sample sample) {
        if (used_ < Capacity) {
            samples_[used_++] = sample;
        }
    }

    std::size_t count() const { return used_; }

private:
    Buffer<Sample, Capacity> samples_{};
    std::size_t used_ = 0;
};

MetricSink<std::vector> heap_sink;
MetricSink<std::list> node_sink;
BoundedMetricSink<std::array, 32> fixed_sink;

