#include <ostream>
#include <vector>

template<class T>
class Column {
public:
    void add(const T& value) { values_.push_back(value); }

    std::size_t size() const { return values_.size(); }

    T total() const {
        T sum{};
        for (const T& value : values_) {
            sum = sum + value;              // requires operator+
        }
        return sum;
    }

    void describe(std::ostream& out) const {
        for (const T& value : values_) {
            out << value << ' ';            // requires operator<<
        }
    }

private:
    std::vector<T> values_;
};

struct Opaque {};

std::size_t opaque_depth() {
    Column<Opaque> column;
    column.add(Opaque{});
    return column.size();   // total() and describe() are never instantiated
}

int int_total(Column<int>& column) {
    return column.total();  // instantiated here, and valid for int
}

// template class Column<Opaque>;
//   An explicit instantiation definition asks for the whole specialization,
//   so every member is instantiated and total()/describe() fail.
//
// auto hook = &Column<Opaque>::total;
//   Forming a pointer to a member function odr-uses it, which requires a
//   definition, which instantiates the body - and fails for the same reason.

enum class State { idle, armed, firing, halted };
enum class Event { arm, trigger, fault, reset };

// Primary: no "next" member at all, so an undefined transition is a compile
// error naming the missing member rather than a silently wrong destination.
template<State From, Event On>
struct Transition {};

template<>
struct Transition<State::idle, Event::arm> {
    static constexpr State next = State::armed;
};

template<>
struct Transition<State::armed, Event::trigger> {
    static constexpr State next = State::firing;
};

template<>
struct Transition<State::firing, Event::reset> {
    static constexpr State next = State::idle;
};

// Partial specialization: a fault halts the machine from any state.
template<State From>
struct Transition<From, Event::fault> {
    static constexpr State next = State::halted;
};

template<State From, Event On>
inline constexpr State next_state = Transition<From, On>::next;

static_assert(next_state<State::idle, Event::arm> == State::armed);
static_assert(next_state<State::armed, Event::trigger> == State::firing);
static_assert(next_state<State::idle, Event::fault> == State::halted);
static_assert(next_state<State::firing, Event::fault> == State::halted);

// next_state<State::idle, Event::trigger> does not compile: the primary
// template matches and has no "next" member.

#include <cstddef>
#include <cstdint>

struct ByteReader {
    using size_type = std::size_t;

    template<class T>
    T read() { return T{}; }
};

template<class Reader>
typename Reader::size_type decode_length(Reader& reader) {
    // Reader::size_type is a dependent qualified name. Without typename the
    // parser must assume it names a non-type, and the declaration fails.
    typename Reader::size_type length =
        // Without the template keyword, the < after read parses as less-than.
        reader.template read<std::size_t>();
    return length;
}

template<class Codec>
struct DecoderBase {
    void reset() {}
    std::uint32_t decode_one() { return 0; }
};

template<class Codec>
struct FrameDecoder : DecoderBase<Codec> {
    std::uint32_t run() {
        // Phase-one unqualified lookup does not search DecoderBase<Codec>: the
        // base is dependent, so its contents are unknown until instantiation.
        this->reset();
        return DecoderBase<Codec>::decode_one();
    }
};

std::size_t use(ByteReader& reader) {
    FrameDecoder<ByteReader> decoder;
    decoder.run();
    return decode_length(reader);
}

