template<class T, template<class...> class Template>
struct IsSpecializationOf : std::false_type {};

template<template<class...> class Template, class... Args>
struct IsSpecializationOf<Template<Args...>, Template> : std::true_type {};

template<class T, template<class...> class Template>
inline constexpr bool is_specialization_of_v =
    IsSpecializationOf<std::remove_cvref_t<T>, Template>::value;

static_assert(is_specialization_of_v<std::tuple<int, double>, std::tuple>);
static_assert(is_specialization_of_v<const std::vector<int>&, std::vector>);
static_assert(!is_specialization_of_v<std::vector<int>, std::tuple>);

// std::array cannot even be *named* as an argument here: the parameter is
// declared template<class...> class, and std::array's second parameter is a
// value. A fixed-shape family needs its own trait with a matching shape.
template<class T>
struct IsStdArray : std::false_type {};

template<class T, std::size_t N>
struct IsStdArray<std::array<T, N>> : std::true_type {};

template<class T>
inline constexpr bool is_std_array_v =
    IsStdArray<std::remove_cvref_t<T>>::value;

static_assert(is_std_array_v<std::array<int, 4>>);
static_assert(is_std_array_v<const std::array<int, 4>&>);
static_assert(!is_std_array_v<std::vector<int>>);

#include <concepts>
#include <cstddef>
#include <cstring>
#include <span>
#include <type_traits>

template<class T>
concept MemberEncodable = requires(const T& value, std::span<std::byte> out) {
    { value.encode(out) } -> std::convertible_to<std::size_t>;
};

template<class T>
concept FreeEncodable = requires(const T& value, std::span<std::byte> out) {
    { encode(value, out) } -> std::convertible_to<std::size_t>;
};

template<class>
inline constexpr bool always_false_v = false;

template<class T>
std::size_t encode_any(const T& value, std::span<std::byte> out) {
    if constexpr (MemberEncodable<T>) {
        return value.encode(out);
    } else if constexpr (FreeEncodable<T>) {
        return encode(value, out);
    } else if constexpr (std::is_trivially_copyable_v<T>) {
        std::memcpy(out.data(), &value, sizeof(T));
        return sizeof(T);
    } else {
        // Dependent condition: false only once T is known, so the message
        // names T instead of firing while the template is parsed.
        static_assert(always_false_v<T>, "no encoding available for T");
    }
}

// The same selection as an overload set. A failure here names the unsatisfied
// concept at the call; the if constexpr version instead reports an error from
// inside whichever branch it chose, which is easier to read once you are in
// the right branch and harder to read when you are not.
template<class T>
    requires std::is_trivially_copyable_v<T>
std::size_t encode_one(const T& value, std::span<std::byte> out) {
    std::memcpy(out.data(), &value, sizeof(T));
    return sizeof(T);
}

template<FreeEncodable T>
std::size_t encode_one(const T& value, std::span<std::byte> out) {
    return encode(value, out);
}

template<MemberEncodable T>
std::size_t encode_one(const T& value, std::span<std::byte> out) {
    return value.encode(out);
}

#include <cstddef>
#include <iostream>
#include <tuple>

template<class... Values>
void print_csv(std::ostream& out, const Values&... values) {
    std::size_t index = 0;
    // Comma fold: the pattern is repeated once per element and the comma
    // operator sequences those repetitions left to right, so index is a
    // reliable "have I written anything yet" flag.
    ((out << (index++ ? "," : "") << values), ...);
    out << '\n';
}

template<class... Values>
void print_tuple(std::ostream& out, const std::tuple<Values...>& values) {
    std::apply(
        [&out](const Values&... elements) { print_csv(out, elements...); },
        values);
}

// Seeded by the first argument rather than by an identity: there is no
// universal identity for "minimum", so an unseeded unary fold would have no
// defined result for an empty pack and no operator to fold over either.
template<class T, class... Rest>
constexpr T min_of(T first, Rest... rest) {
    T best = first;
    ((best = rest < best ? static_cast<T>(rest) : best), ...);
    return best;
}

static_assert(min_of(4) == 4);
static_assert(min_of(4, 2, 9) == 2);

void demo() {
    print_csv(std::cout);                       // just a newline
    print_csv(std::cout, 1, 2.5, "bid");        // 1,2.5,bid
    print_tuple(std::cout, std::tuple{7, 'x'}); // 7,x
}

