writing.solution:
#include <string>
#include <utility>

struct Outcome {
    bool ok;
    int code;
};

template<class Action, class... Args>
Outcome with_retry(int attempts, Action&& action, Args&&... arguments) {
    for (int attempt = 1; attempt < attempts; ++attempt) {
        // Deliberately NOT forwarded. Every named parameter is an lvalue here,
        // so the callable sees lvalues and cannot consume the arguments. Write
        // std::forward inside the loop and attempt 2 works on the wreckage
        // attempt 1 left behind: a moved-from string, an emptied vector, a
        // null unique_ptr.
        Outcome outcome = action(arguments...);
        if (outcome.ok) {
            return outcome;
        }
    }

    // Last attempt: nothing follows it, so the arguments may now be consumed
    // and the caller's value categories are restored exactly.
    return std::forward<Action>(action)(std::forward<Args>(arguments)...);
}

Outcome send_once(const std::string& payload);

Outcome send_with_retry(std::string payload) {
    return with_retry(
        3,
        [](const std::string& body) { return send_once(body); },
        std::move(payload));
}

// ---- codec.hpp ----
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>

// The type-independent core: one non-template function, compiled once. Every
// specialization of encode() below shrinks to an address, a size and a call.
std::size_t encode_bytes(const void* source,
                         std::size_t size,
                         std::span<std::byte> out);

template<class Message>
std::size_t encode(const Message& message, std::span<std::byte> out) {
    return encode_bytes(&message, sizeof(Message), out);
}

struct Heartbeat {
    std::uint64_t sent_at;
};

struct Reject {
    std::uint32_t code;
};

// The two hot specializations are promised to exist elsewhere, so including
// translation units stop substituting and emitting them. Other message types
// are unaffected and still instantiate implicitly from this header.
extern template std::size_t encode<Heartbeat>(const Heartbeat&,
                                              std::span<std::byte>);
extern template std::size_t encode<Reject>(const Reject&,
                                           std::span<std::byte>);

// ---- codec.cpp ----
// (would #include "codec.hpp")

std::size_t encode_bytes(const void* source,
                         std::size_t size,
                         std::span<std::byte> out) {
    if (out.size() < size) {
        return 0;
    }
    std::memcpy(out.data(), source, size);
    return size;
}

// Exactly one explicit instantiation definition per promised specialization.
// Delete either one and the program still compiles everywhere and fails at
// link time with an undefined symbol - the front end has no way to know the
// promise was unkept.
template std::size_t encode<Heartbeat>(const Heartbeat&,
                                       std::span<std::byte>);
template std::size_t encode<Reject>(const Reject&, std::span<std::byte>);

// ---- strategy.cpp ----
// (would #include "codec.hpp")

struct Cancel {
    std::uint64_t order_id;
};

std::size_t emit(const Heartbeat& heartbeat,
                 const Cancel& cancel,
                 std::span<std::byte> out) {
    // Heartbeat resolves to the pre-built specialization; Cancel is
    // instantiated here as usual.
    return encode(heartbeat, out) + encode(cancel, out);
}
